<template>
  <div class="profile-view bg-light min-vh-100">
    <CompanyNavBar v-if="user.userRole === 0" />
    <NavBarVue v-else />

    <b-container class="py-5">
      <b-row class="justify-content-center">
        <b-col lg="10">
          <b-overlay :show="isLoading" rounded="lg" opacity="0.6">
            <div
              class="profile-header shadow-sm mb-4 text-white overflow-hidden"
            >
              <div class="header-gradient p-4 d-flex align-items-center">
                <div class="profile-avatar shadow mr-4">
                  {{ user.name.charAt(0) }}
                </div>
                <div>
                  <h2 class="mb-0 font-weight-bold">{{ user.name }}</h2>
                  <b-badge
                    pill
                    variant="mbr-gold"
                    class="text-uppercase px-3 py-1 mt-2"
                  >
                    <b-icon icon="shield-lock" class="mr-1"></b-icon>
                    {{ convertRole(user.userRole) }}
                  </b-badge>
                </div>
              </div>
            </div>

            <b-row>
              <b-col md="5" class="mb-4">
                <b-card class="border-0 shadow-sm h-100">
                  <h6 class="font-weight-bold text-mbr-green mb-4">
                    <b-icon icon="info-circle" class="mr-2"></b-icon>Informações
                    da Conta
                  </h6>

                  <div class="info-item mb-3">
                    <small class="text-muted d-block">E-mail</small>
                    <span class="font-weight-600">{{ user.email }}</span>
                  </div>

                  <div class="info-item mb-3">
                    <small class="text-muted d-block">Telemóvel</small>
                    <span class="font-weight-600">{{ user.phone }}</span>
                  </div>

                  <div class="info-item mb-3">
                    <small class="text-muted d-block">Membro desde</small>
                    <span
                      class="text-dark"
                      v-date-format="user.createdAt"
                    ></span>
                  </div>

                  <div class="info-item">
                    <small class="text-muted d-block">Status</small>
                    <b-badge
                      :variant="
                        user.status === 1 ? 'soft-success' : 'soft-danger'
                      "
                    >
                      {{ user.status === 1 ? "Ativo" : "Bloqueado" }}
                    </b-badge>
                  </div>
                </b-card>
              </b-col>

              <b-col md="7" class="mb-4">
                <b-card class="border-0 shadow-sm border-top-mbr">
                  <h6 class="font-weight-bold text-dark mb-3">
                    <b-icon icon="key-fill" class="mr-2 text-mbr-green"></b-icon
                    >Segurança e Acesso
                  </h6>

                  <b-alert
                    :show="updatedPassword == 0"
                    variant="danger"
                    class="small py-2 shadow-sm border-0"
                  >
                    <b-icon
                      icon="exclamation-triangle-fill"
                      class="mr-2"
                    ></b-icon>
                    Sua conta está usando uma senha temporária. Altere-a agora
                    para sua segurança.
                  </b-alert>

                  <b-form @submit.prevent="updatePassword">
                    <b-form-group
                      label="Senha Atual"
                      label-class="small font-weight-bold"
                    >
                      <b-form-input
                        v-model="form.password"
                        type="password"
                        size="sm"
                        placeholder="••••••••"
                        class="bg-light border-0"
                        required
                      ></b-form-input>
                    </b-form-group>

                    <b-row>
                      <b-col sm="6">
                        <b-form-group
                          label="Nova Senha"
                          label-class="small font-weight-bold"
                        >
                          <b-form-input
                            v-model="form.newPassword"
                            type="password"
                            size="sm"
                            placeholder="Mínimo 6 caracteres"
                            class="bg-light border-0"
                            required
                          ></b-form-input>
                        </b-form-group>
                      </b-col>
                      <b-col sm="6">
                        <b-form-group
                          label="Confirmar Nova Senha"
                          label-class="small font-weight-bold"
                        >
                          <b-form-input
                            v-model="form.confirmPassword"
                            type="password"
                            size="sm"
                            placeholder="Repita a senha"
                            class="bg-light border-0"
                            required
                          ></b-form-input>
                        </b-form-group>
                      </b-col>
                    </b-row>

                    <div class="text-right mt-3">
                      <b-button
                        :disabled="isLoading"
                        type="submit"
                        variant="mbr-green"
                        class="px-4 shadow-sm"
                        size="sm"
                      >
                        <b-icon icon="check-circle" class="mr-1"></b-icon>
                        Atualizar Senha
                      </b-button>
                    </div>
                  </b-form>
                </b-card>
              </b-col>
            </b-row>
          </b-overlay>
        </b-col>
      </b-row>
    </b-container>
  </div>
</template>

<script>
import { mapGetters } from "vuex";
import axios from "axios";

import NavBarVue from "@/components/NavBar";
import CompanyNavBar from "@/components/CompanyNavBar.vue";
import logs from "@/utils/logs";

export default {
  name: "ProfileView",

  data: () => ({
    form: {
      name: "",
      email: "",
      phone: "",
      password: "",
      newPassword: "",
      confirmPassword: "",
      companyId: "",
      userRole: "",
      status: "",
      createdAt: "",
      updatedAt: "",
    },
  }),

  components: {
    NavBarVue,
    CompanyNavBar,
  },

  created() {
    this.form = this.user;
    this.form.password = "";
    this.form.newPassword = "";
    this.form.confirmPassword = "";
  },

  computed: {
    ...mapGetters(["isLoading", "user", "token", "updatedPassword"]),
  },

  methods: {
    updatePassword() {
      if (
        this.form.password.length < 4 ||
        this.form.newPassword.length < 6 ||
        this.form.confirmPassword < 6
      ) {
        this.showToast(
          "Aviso!",
          "warning",
          "As senhas devem conter no mínimo 6 caracteres."
        );
        return;
      } else {
        if (this.form.newPassword != this.form.confirmPassword) {
          this.showToast("Aviso!", "warning", "As senhas não coincidem.");
        } else {
          const passingValues = {
            password: this.form.password,
            newPassword: this.form.newPassword,
            email: this.form.email,
            updatedPassword: 1,
          };
          this.$store.commit("LOADING_STATUS", true);
          axios
            .post(`/api/updatePassword`, passingValues)
            .then((res) => {
              const data = res.data;
              if (data.success == true) {
                this.showToast("Sucesso!", "success", data.message);
                this.logoutUser();
              } else {
                this.showToast("Erro!", "danger", data.message);
              }
              this.$store.commit("LOADING_STATUS", false);
              this.resetForm();
            })
            .catch((err) => {
              this.showToast("Erro!", "danger", err.message);
              this.$store.commit("LOADING_STATUS", false);
              this.resetForm();
            });
        }
      }
    },

    resetForm() {
      this.form = this.user;
      this.form.password = "";
      this.form.newPassword = "";
      this.form.confirmPassword = "";
    },

    showToast(title, variant, msg) {
      this.$bvToast.toast(`${msg}`, {
        title,
        variant,
        solid: true,
        toaster: "b-toaster-top-center",
        autoHideDelay: 5000,
      });
    },

    convertRole(role) {
      if (role == -1) {
        return "Front Office";
      } else if (role == 0) {
        return "Súper Admin";
      } else if (role == 1) {
        return "Admin";
      } else if (role == 2) {
        return "Atendimento";
      } else if (role == 3) {
        return "Avalista";
      }
    },

    convertStatus(status) {
      if (status === 1) {
        return "Activo";
      } else if (status === 0) {
        return "Bloaqueado";
      }
    },

    logoutUser() {
      const logsParams = logs(
        this.user,
        `${this.user.email} - ${this.user.name} Actualização da senha.`,
        "Autenticação"
      );
      this.$store.dispatch("addLog", logsParams).then(() => {
        this.$store.dispatch("actionDoLogout");
        this.$router.push("/");
      });
    },
  },
};
</script>
<style scoped>
/* CORES E GRADIENTES MBR */
.text-mbr-green {
  color: #009640 !important;
}
.btn-mbr-green {
  background-color: #009640;
  color: white;
  border: none;
  font-weight: 600;
}
.btn-mbr-green:hover {
  background-color: #007a33;
  color: white;
}

.header-gradient {
  background: linear-gradient(135deg, #009640 0%, #004d21 100%);
  border-radius: 15px;
}

.badge-mbr-gold {
  background-color: #c5a065;
  color: white;
}

/* AVATAR CIRCULAR */
.profile-avatar {
  width: 80px;
  height: 80px;
  background-color: white;
  color: #009640;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2.5rem;
  font-weight: bold;
}

/* CARDS E BORDAS */
.border-top-mbr {
  border-top: 4px solid #009640 !important;
}
.font-weight-600 {
  font-weight: 600;
}

.info-item small {
  text-transform: uppercase;
  letter-spacing: 0.5px;
  font-weight: 700;
}

/* BADGES SUAVES */
.badge-soft-success {
  background-color: rgba(40, 167, 69, 0.1);
  color: #28a745;
}
.badge-soft-danger {
  background-color: rgba(220, 53, 69, 0.1);
  color: #dc3545;
}

/* INPUTS */
.form-control:focus {
  background-color: #fff !important;
  box-shadow: 0 0 0 0.2rem rgba(0, 150, 64, 0.15);
  border-color: #009640 !important;
}
</style>
